package dev.saffron;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;

@Service class NotificationInbox {
 private final JdbcTemplate db;private final ChannelOperations channels;
 NotificationInbox(JdbcTemplate db,ChannelOperations channels){this.db=db;this.channels=channels;}
 @Transactional public void send(String key,String subject,String type,UUID resource,String title,String href){
  if(key.length()>250||type.length()>80||title.length()>200||!href.matches("/(support|reviews|notifications|orders/[a-f0-9-]{36})"))throw new IllegalArgumentException("Invalid notification template");
  var inserted=db.queryForList("insert into notifications(id,event_key,audience,subject,type,resource_id,title,href) values(?,?,?,?,?,?,?,?) on conflict(event_key) do nothing returning id",UUID.randomUUID(),key,subject==null?"ADMIN":"SUBJECT",subject,type,resource,title,href);if(subject!=null&&!inserted.isEmpty())channels.enqueue((UUID)inserted.getFirst().get("id"),subject);
 }
 void support(Map<String,Object> ticket,String type,boolean customer,boolean operators){UUID id=(UUID)ticket.get("id");String key="support:"+id+":"+ticket.get("version")+":"+type;if(customer)send(key+":customer",ticket.get("customer_subject").toString(),type,id,supportTitle(type),"/support");if(operators)send(key+":operators",null,type,id,supportTitle(type),"/support");}
 static String supportTitle(String type){return switch(type){case "SUPPORT_OPENED"->"Your order support request is open";case "SUPPORT_REPLIED"->"A support conversation has a new reply";case "SUPPORT_ESCALATED"->"A support request has been escalated";case "SUPPORT_ACKNOWLEDGED"->"An administrator acknowledged your escalation";case "SUPPORT_REFUND"->"Your support refund was approved; confirmation is pending";case "SUPPORT_RESOLVE"->"Your support request was resolved";default->throw new IllegalArgumentException("Unknown support notification");};}
 void review(Map<String,Object> review,String type,boolean operators){UUID id=(UUID)review.get("id");String key="review:"+id+":"+review.get("version")+":"+type;String title=switch(type){case "REVIEW_CREATED"->"Your verified-order review was published";case "REVIEW_EDITED"->"Your review changes were saved";case "REVIEW_HIDDEN"->"Your review was hidden by moderation";case "REVIEW_RESTORED"->"Your review was restored by moderation";default->throw new IllegalArgumentException("Unknown review notification");};send(key+":customer",review.get("customer_subject").toString(),type,id,title,"/orders/"+review.get("order_id"));if(operators)send(key+":operators",null,type,id,"A review was edited; inspect its current version","/reviews");}
 void order(UUID order,String type){String title=orderTitle(type);if(title==null)return;var o=db.queryForMap("select customer_name,version from orders where id=?",order);send("order:"+order+":"+o.get("version")+":"+type,o.get("customer_name").toString(),type,order,title,"/orders/"+order);}
 static String orderTitle(String type){return switch(type){case "CheckoutStarted"->"Your order is awaiting payment";case "OrderPlaced"->"Your order is confirmed";case "OrderACCEPTED"->"The restaurant accepted your order";case "OrderPREPARING"->"The kitchen is preparing your meal";case "OrderREADY"->"Your meal is ready for pickup";case "OrderASSIGNED"->"A delivery partner was assigned";case "OrderPICKED_UP"->"Your delivery partner picked up your meal";case "OrderDELIVERED"->"Your order was delivered";case "OrderCANCELLED"->"Your order was cancelled; check payment status";case "PaymentSucceeded"->"Your payment is confirmed";case "PaymentFailed"->"Payment was not confirmed; review your order";case "PaymentExpired"->"Your payment session expired";case "RefundCompleted"->"A refund is confirmed by the payment provider";case "RefundUpdated"->"A refund status changed; check your order";default->null;};}
 public Map<String,Object> list(String subject,boolean admin,long before){if(before<1)throw new IllegalArgumentException("Invalid notification cursor");var rows=db.queryForList("select n.id,n.sequence,n.type,n.resource_id,n.title,n.href,n.created_at,(r.read_at is not null) is_read from notifications n left join notification_receipts r on r.notification_id=n.id and r.subject=? where (n.subject=? or (? and n.audience='ADMIN')) and n.sequence<? order by n.sequence desc limit 51",subject,subject,admin,before);boolean more=rows.size()>50;if(more)rows.removeLast();long unread=db.queryForObject("select count(*) from notifications n where (n.subject=? or (? and n.audience='ADMIN')) and not exists(select 1 from notification_receipts r where r.notification_id=n.id and r.subject=?)",Long.class,subject,admin,subject);Map<String,Object> result=new HashMap<>();result.put("items",rows);result.put("unreadCount",unread);result.put("nextCursor",more?rows.getLast().get("sequence"):null);return result;}
 @Transactional public void read(String subject,boolean admin,UUID id){int count=db.update("insert into notification_receipts(notification_id,subject) select id,? from notifications where id=? and (subject=? or (? and audience='ADMIN')) on conflict do nothing",subject,id,subject,admin);if(count==0&&db.queryForObject("select count(*) from notifications where id=? and (subject=? or (? and audience='ADMIN'))",Integer.class,id,subject,admin)==0)throw new ResponseStatusException(NOT_FOUND);}
}
